y AS (SELECT d.sk_municipio, (p.j-1)/1095 AS k, p.pred FROM p JOIN m ON m.i = ((p.j-1) % 1095) + 1 JOIN dw.dim_municipio d ON d.cod_dane_mpio = m.cod),
z AS (SELECT sk_municipio, CASE WHEN k < 6 THEN 2025 ELSE 2026 END AS anio, CASE WHEN k < 6 THEN 7 + k ELSE k - 5 END AS mes, pred FROM y),
r AS (SELECT f.sk_municipio, t.anio, t.mes, SUM(f.cantidad_victimas) AS v FROM dw.fact_hurto_personas f JOIN dw.dim_tiempo t ON t.sk_tiempo = f.sk_tiempo WHERE t.anio = 2025 AND t.mes >= 7 GROUP BY 1, 2, 3)
SELECT z.sk_municipio, CASE WHEN z.anio = 2025 THEN z.anio * 10000 + z.mes * 100 + 1 END, z.anio, z.mes,
       CASE WHEN z.anio = 2025 THEN 'Prueba 2025' ELSE 'Pronóstico 2026' END,
       CASE WHEN z.anio = 2025 THEN COALESCE(r.v, 0) END, z.pred,
       CASE WHEN z.anio = 2025 THEN ABS(z.pred - COALESCE(r.v, 0)) END, 'Bosque aleatorio', CURRENT_DATE
FROM z LEFT JOIN r ON r.sk_municipio = z.sk_municipio AND r.anio = z.anio AND r.mes = z.mes;
